import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.charset.StandardCharsets;



class Main {
    public static void main(String[] args) throws Exception {
        Path path = Files.createTempFile("marks-", ".txt");
        try {
            Files.writeString(path, "40\n80\n", StandardCharsets.UTF_8);
            String text = Files.readString(path, StandardCharsets.UTF_8);
            System.out.print(text);
        } finally {
            Files.deleteIfExists(path);
        }
    }
}

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.charset.StandardCharsets;
import java.io.BufferedReader;
import java.io.BufferedWriter;



class Main {
    public static void main(String[] args) throws Exception {
        Path path = Files.createTempFile("report-", ".txt");
        try {
            try (BufferedWriter writer = Files.newBufferedWriter(path, StandardCharsets.UTF_8)) {
                writer.write("CSE 80");
                writer.newLine();
                writer.write("MAT 75");
                writer.newLine();
            }
            try (BufferedReader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8)) {
                String line;
                while ((line = reader.readLine()) != null) { System.out.println(line); }
            }
        } finally {
            Files.deleteIfExists(path);
        }
    }
}

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.charset.StandardCharsets;
import java.nio.file.NoSuchFileException;



class Main {
    public static void main(String[] args) throws Exception {
        Path directory = Files.createTempDirectory("library-");
        try {
            try {
                Files.readString(directory.resolve("absent.txt"), StandardCharsets.UTF_8);
            } catch (NoSuchFileException failure) {
                System.out.println("File not found");
            }
            System.out.println("Menu continues");
        } finally {
            Files.delete(directory);
        }
    }
}
